package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.application.AiSafetyPolicy;import com.yuegang.zhihui.ai.domain.RetrievalGateway;import com.yuegang.zhihui.search.api.SearchHit;import java.util.*;public final class GovernedRetrievalGateway implements RetrievalGateway{private final RetrievalGateway delegate;private final AiSafetyPolicy policy;public GovernedRetrievalGateway(RetrievalGateway d,AiSafetyPolicy p){delegate=d;policy=p;}public List<SearchHit>search(String query,String category,int limit){policy.guard(query,category);return delegate.search(query,category,limit);}}
